"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[2071],{22071:e=>{e.exports=JSON.parse('{"slug":"vvp-kitaya-3-kvartal-2026-eksport","locale":"ru","title":"Экономика Китая ускорилась до 4,5% на экспорте, а розничные продажи выросли всего на 1,1%","description":"ВВП Китая в III квартале 2026 года вырос на 4,5%. Экспорт прибавил 36%, розница 1,1%. Почему рост на внешнем спросе хрупкий и что это значит для России.","blocks":[{"id":"b001","kind":"paragraph","text":"ВВП Китая в июле–сентябре вырос на 4,5% к тому же периоду 2025 года, данные опубликовали 19 октября. Аналитики ждали 4,4%. Во II квартале рост был 4,3%, минимальный с 2022 года. К предыдущему кварталу экономика прибавила 1,2%. За 9 месяцев рост составил 4,6%, а ВВП за это время — 107,1 трлн юаней. Цель правительства на год 4,5–5%, и после этих данных она выглядит достижимой."},{"id":"b002","kind":"paragraph","text":"Главный вклад дал экспорт. В сентябре он вырос на 36,3% к прошлому году, импорт на 31%. За месяц Китай продал за рубеж товаров на $133,5 млрд больше, чем купил, это крупнейший разрыв за 20 месяцев. Экспорт микросхем за 9 месяцев вырос в деньгах вдвое, компьютеров и автомобилей примерно на 54%. Промышленное производство в сентябре выросло на 5,5%."},{"id":"b003","kind":"paragraph","text":"Внутри страны картина другая. Розничные продажи в сентябре выросли на 1,1%, это лучше ожиданий 0,5%, но всё равно мало. Инвестиции в основной капитал за 9 месяцев снизились на 7,2%, частные на 10,4%, вложения в строительство жилья на 20,6%. Продажи новых квартир по площади упали на 13,2%. Большая часть сбережений китайских семей вложена в квартиры, и когда жильё дешевеет, люди чувствуют себя беднее и тратят осторожнее."},{"id":"b004","kind":"paragraph","text":"Представим семейное кафе, которое начало возить пироги в соседний город. Выручка растёт, повара заняты, но жители своего района заходят всё реже. Пока соседи покупают, кафе живёт хорошо. Стоит им найти другую пекарню, и рост закончится, потому что своих клиентов кафе не нарастило. Экономисты называют это ростом за счёт внешнего спроса. Он быстрый, но зависит от чужих решений: Евросоюз уже добивается, чтобы Китай меньше продавал ему дорогих товаров."},{"id":"b005","kind":"paragraph","text":"Для России это вопрос экспортной выручки. Китай крупнейший покупатель российского топлива: в сентябре он купил нефти, газа и угля примерно на 9,1 млрд евро. Загруженные заводы потребляют больше энергии, и пока экспортные заказы идут, спрос на сырьё держится. Сильные данные уменьшают шансы на новые меры поддержки внутреннего спроса: когда план выполняется, у Пекина меньше причин тратить деньги на стимулы."},{"id":"b006","kind":"paragraph","text":"Старший экономист Economist Intelligence Unit Тяньчэнь Сюй ждёт, что экспорт и государственные инвестиции поддержат рост и в IV квартале. Риск в том, что опора одна. Замедление мировых вложений в искусственный интеллект или барьеры Евросоюза ударят по продажам микросхем и машин, а свои покупатели пока не готовы заменить чужих. Сохранение экспортного спроса держит заводы Китая загруженными, а вместе с ними и закупки российской нефти. Его ослабление проверит, насколько быстро Пекин сможет разогнать потребление внутри страны."},{"id":"b007","kind":"heading","text":"Насколько вырос ВВП Китая в III квартале 2026 года?"},{"id":"b008","kind":"paragraph","text":"На 4,5% к июлю–сентябрю 2025 года. Аналитики ждали 4,4%, во II квартале рост был 4,3%, минимальный с 2022 года. За 9 месяцев экономика выросла на 4,6% при цели правительства 4,5–5%."},{"id":"b009","kind":"heading","text":"Почему рост Китая называют несбалансированным?"},{"id":"b010","kind":"paragraph","text":"Экспорт в сентябре вырос на 36,3%, а розничные продажи на 1,1%. Инвестиции в недвижимость за 9 месяцев упали на 20,6%. Экономика растёт за счёт покупателей за рубежом, а не собственных жителей."},{"id":"b011","kind":"heading","text":"Что ускорение Китая значит для России?"},{"id":"b012","kind":"paragraph","text":"Китай крупнейший покупатель российской нефти, газа и угля. Пока его заводы загружены экспортными заказами, спрос на топливо держится. Если внешний спрос ослабнет, внутренний рынок Китая пока не готов его заменить."}],"sources":[{"label":"ВВП Китая в III квартале вырос на 4,5%","url":"https://www.interfax.ru/business/1123374"},{"label":"China\'s economic growth quickens as exports surge","url":"https://www.cnbc.com/2026/10/19/chinas-economic-growth-quickens-to-4point6percent-as-exports-surge-stimulus-rolls-out.html"},{"label":"China\'s Growth Rebounds to 4.5%, Puts Annual Target Within Reach","url":"https://www.bloomberg.com/news/articles/2026-10-19/china-s-growth-rebounds-to-4-5-puts-annual-target-within-reach"},{"label":"China Q3 GDP beats forecasts at 4.5%, retail sales grow at fastest pace since March","url":"https://investinglive.com/news/china-q3-gdp-beats-forecasts-at-4-5-retail-sales-grow-at-fastest-pace-since-march/"},{"label":"China\'s economy holds steady in first three quarters of 2026","url":"https://www.indexbox.io/blog/chinas-economy-holds-steady-in-first-three-quarters-of-2026-as-trade-and-industry-outpace-broader-growth/"},{"label":"China\'s exports surge 36.3% in September as pressure ramps up to rebalance trade","url":"https://clickondetroit.com/business/2026/10/14/chinas-exports-surge-363-in-september-as-pressure-ramps-up-to-rebalance-trade"},{"label":"China Posts Biggest Trade Surplus in 20 Months","url":"https://tradingeconomics.com/china/balance-of-trade/news/591695"},{"label":"September 2026 — Monthly analysis of Russian fossil fuel exports and sanctions","url":"https://energyandcleanair.org/september-2026-monthly-analysis-of-russian-fossil-fuel-exports-and-sanctions/"}],"sourceBodySha256":"a43116f5bc45095d81495bfb1beae8eb81d22f98eafffb5342e2297d883572c6"}')}}]);